import{_ as e,o as t,c as r,a2 as l}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"快速鍵設定","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/settings/hotkeys-page.md","filePath":"zh-TW/user-guide/settings/hotkeys-page.md","lastUpdated":1787758874000}'),s={name:"zh-TW/user-guide/settings/hotkeys-page.md"};function a(n,o,i,c,d,g){return t(),r("div",null,[...o[0]||(o[0]=[l('<h1 id="快速鍵設定" tabindex="-1">快速鍵設定 <a class="header-anchor" href="#快速鍵設定" aria-label="Permalink to &quot;快速鍵設定&quot;">​</a></h1><p>快速鍵設定頁面集中管理 Lertaro 的所有全域呼出按鍵、應用程式內導覽快速鍵、外掛模組動作快捷方式以及前景處理程序過濾規則。頁面頂部包含三個索引標籤頁：<strong>全域</strong>、<strong>外掛模組動作</strong>與<strong>處理程序黑名單</strong>。</p><h2 id="_1-全域-global" tabindex="-1">1. 全域（Global） <a class="header-anchor" href="#_1-全域-global" aria-label="Permalink to &quot;1. 全域（Global）&quot;">​</a></h2><h3 id="全域快速鍵分組" tabindex="-1">全域快速鍵分組 <a class="header-anchor" href="#全域快速鍵分組" aria-label="Permalink to &quot;全域快速鍵分組&quot;">​</a></h3><ul><li><strong>顯示/隱藏快速搜尋</strong>：專屬按鍵錄製框。支援錄製為<strong>單鍵連按兩下模式</strong>（預設按兩下 <code>Ctrl</code>，亦可設為按兩下 <code>Alt</code> 或 <code>Shift</code>），或錄製為<strong>常規組合鍵</strong>（如 <code>Alt+Space</code>、<code>Win+Space</code> 等）。</li><li><strong>預設開啟完整面板</strong>：核取方塊（預設關閉）。開啟後，全域呼出快速鍵會改為開啟或切換主視窗，而不是快速視窗。透過此快速鍵開啟時，主視窗會強制置於其他視窗之上；透過「開啟完整搜尋主視窗」、工作列功能表或其他入口開啟時，不會強制釘在最上層。</li><li><strong>全螢幕應用程式聚焦時仍然回應</strong>：核取方塊（預設關閉）。開啟後，即使前景有獨占全螢幕程式（如全螢幕遊戲或影片），Lertaro 依然會回應快速鍵呼出搜尋框；保持關閉則自動放行按鍵不搶佔焦點。</li><li><strong>快速跳轉（Quick Jump）</strong>：預設 <code>Ctrl+G</code>。在各類檔案對話方塊中按下即可直接跳轉到最近在檔案管理器中瀏覽過的目錄。</li></ul><h3 id="功能按鍵分組" tabindex="-1">功能按鍵分組 <a class="header-anchor" href="#功能按鍵分組" aria-label="Permalink to &quot;功能按鍵分組&quot;">​</a></h3><p>頁面提供了一系列獨立的按鍵錄製控制項，支援任意單鍵或組合鍵錄製：</p><ul><li><strong>選取下一項 / 上一項</strong>：預設 <code>Ctrl+N</code> / <code>Ctrl+P</code>（與方向鍵 <code>↓</code> / <code>↑</code> 等效）。</li><li><strong>跳轉結果修飾鍵</strong>：預設 <code>Ctrl</code>，配合數字鍵 <code>1</code>–<code>9</code> 即可在快速視窗中直達前 9 項結果。</li><li><strong>開啟動作功能表</strong>：預設 <code>Ctrl+O</code>（與方向鍵 <code>→</code> 等效）。</li><li><strong>從選取項補全搜尋詞</strong>：預設 <code>Ctrl+Tab</code>。</li><li><strong>QuickLook 即時預覽</strong>：預設 <code>Alt+P</code>。</li><li><strong>上/下一條關鍵字歷程</strong>：預設 <code>Alt+Up</code> / <code>Alt+Down</code>。</li><li><strong>刪除目前關鍵字歷程</strong>：預設 <code>Ctrl+Delete</code>。</li><li><strong>開啟完整搜尋主視窗</strong>：預設 <code>Ctrl+F</code>。</li><li><strong>開啟傳送視窗（LocalSend）</strong>：預設 <code>Ctrl+S</code>。</li><li><strong>保持視窗不消失（釘住）</strong>：預設 <code>Ctrl+T</code>。</li><li><strong>呼出/關閉快速面板</strong>：預設 <code>Ctrl+F2</code>。</li></ul><h3 id="快速導覽滑鼠觸發分組" tabindex="-1">快速導覽滑鼠觸發分組 <a class="header-anchor" href="#快速導覽滑鼠觸發分組" aria-label="Permalink to &quot;快速導覽滑鼠觸發分組&quot;">​</a></h3><ul><li><strong>在空白處按兩下左鍵</strong>：核取方塊（預設開啟）。在桌面或檔案總管空白處按兩下快顯快速導覽功能表。</li><li><strong>在空白處按一下中鍵</strong>：核取方塊（預設開啟）。在桌面、檔案總管或檔案選取對話方塊中按一下滑鼠中鍵快顯快速導覽功能表。</li></ul><h2 id="_2-外掛模組動作-plugin-actions" tabindex="-1">2. 外掛模組動作（Plugin Actions） <a class="header-anchor" href="#_2-外掛模組動作-plugin-actions" aria-label="Permalink to &quot;2. 外掛模組動作（Plugin Actions）&quot;">​</a></h2><p>各外掛模組註冊的專屬動作快速鍵（例如內建的檔案操作：複製路徑 <code>Ctrl+Shift+C</code>、剪下 <code>Ctrl+X</code>、複製 <code>Ctrl+C</code>、貼上 <code>Ctrl+V</code>、刪除 <code>Delete</code>、徹底刪除 <code>Shift+Delete</code> 等）均匯集於此。</p><ul><li><strong>分組檢視</strong>：按註冊動作的來源外掛模組清晰分組。</li><li><strong>獨立重錄</strong>：每個動作均配有專屬的按鍵錄製框，按一下即可按下新按鍵進行覆蓋綁定。</li></ul><h2 id="_3-處理程序黑名單-process-blacklist" tabindex="-1">3. 處理程序黑名單（Process Blacklist） <a class="header-anchor" href="#_3-處理程序黑名單-process-blacklist" aria-label="Permalink to &quot;3. 處理程序黑名單（Process Blacklist）&quot;">​</a></h2><p>用於設定特定前景應用程式的無訊息放行機制。當黑名單中的程式處於系統前景聚焦狀態時，Lertaro 會完全放行所有全域快速鍵與滑鼠觸發手勢，絕不進行攔截。</p><ul><li><strong>不區分大小寫</strong>：新增 <code>game.exe</code> 或 <code>game</code> 均可生效。</li><li><strong>單筆新增</strong>：在單筆輸入框中輸入處理程序名稱，按一下<strong>新增處理程序</strong>按鈕。</li><li><strong>批次管理</strong>：支援按一下<strong>產生文字</strong>將目前黑名單匯出為多行文字，或在多行文字方塊中直接貼上編輯後按一下<strong>套用到清單</strong>進行一鍵批次匯入。</li><li><strong>檔案對話方塊安全豁免</strong>：即使某個程式處於黑名單中，當它快顯系統檔案選取對話方塊時，Lertaro 的內嵌搜尋與滑鼠快速導覽依然會被安全放行，確保檔案選取效率不受影響。</li></ul>',16)])])}const p=e(s,[["render",a]]);export{u as __pageData,p as default};
